class Dinic:
 def __init__(self,n):self.g=[[] for _ in range(n)]
 def edge(self,u,v,c):
  self.g[u].append([v,c,len(self.g[v]),c]);self.g[v].append([u,0,len(self.g[u])-1,0])
 def flow(self,s,t,limit=10**9):
  total=0;n=len(self.g)
  while total<limit:
   level=[-1]*n;level[s]=0;q=collections.deque([s])
   while q:
    u=q.popleft()
    for v,c,rev,orig in self.g[u]:
     if c and level[v]<0:level[v]=level[u]+1;q.append(v)
   if level[t]<0:break
   it=[0]*n
   def dfs(u,f):
    if u==t:return f
    while it[u]<len(self.g[u]):
     e=self.g[u][it[u]];v,c,rev,orig=e
     if c and level[v]==level[u]+1:
      d=dfs(v,min(f,c))
      if d:e[1]-=d;self.g[v][rev][1]+=d;return d
     it[u]+=1
    return 0
   while total<limit:
    d=dfs(s,limit-total)
    if not d:break
    total+=d
  return total
